for(const {id,overall} of r.ranking){const v=JSON.parse(await readFile(`${root}/${id}/verdict.json`,'utf8')); assert.equal(v.id,id); assert.equal(Object.keys(v.rubric).length,10); assert.equal(Object.keys(v.traps).length,8); assert.equal(v.overall,Object.values(v.rubric).reduce((s,x)=>s+x.score,0)); assert.equal(overall,v.overall); assert.equal(v.hiddenTests.countedTotal,16); for(const t of Object.values(v.traps)) assert.ok(['yes','partial','no'].includes(t.handled));}
console.log('Validated seven verdicts, eight traps and ten criterion scores each, plus ranking totals.');
